        const hasOtherDistinctLesionCF = /fracture.*(?:humerus|bassin|cote|radius|poignet|vertebr|clavicule|rotule|tibia|p[eé]ron[eé]|fibula|cheville|mall[eé]ol)|luxation.*(?:epaule|genou)/i.test(normalized);
